// Captures what the Queue app's write routes (POST, PATCH, PUT, DELETE) put on the wire and leave in the database, by running
// the real Queue Route Handlers (apps/queue/src/app/api) and the real @rotra/db services (Prisma) against a throwaway local
// Postgres. The harness is capture-writes-base.mjs; the Go side is apps/api/internal/writetest. Groups so far:
//   roster     POST /api/sessions/{sessionId}/roster/batch   (the offline contract: ordered replay, repeat-safe on operationId)
//   rosterops  the single roster operations (add, remove, level, no show, move to waitlist, games, presence, waitlist)
//   club       the club's writes (invite link, venues, settings, saved players: add, delete, move, club nickname, registration link)
//   prep       session preparation and courts (create, edit, join switches, start, delete, the court commands); run with TZ=UTC
//
//   docker run -d --rm --name rotra-capture-pg -e POSTGRES_PASSWORD=test -p 127.0.0.1:55439:5432 postgres:16-alpine
//   source ~/.nvm/nvm.sh && nvm use
//   ROTRA_CAPTURE_DB_URL=postgres://postgres:test@127.0.0.1:55439/postgres \
//     node node_modules/.pnpm/vitest@*/node_modules/vitest/vitest.mjs run --config apps/api/testdata/tools/vitest.capture.config.mjs apps/api/testdata/tools/capture-writes-queue.test.mjs [-t roster]
//
// Refuses any host but 127.0.0.1/localhost. It creates its own database (rotra_capture_<n>) and drops it.
// Output: apps/api/internal/queuewrites/testdata/<group>.golden.json (commit it). The cases are generated by
// gen-writes-queue-cases.py and gen-writes-queue-ops-cases.py; the seed (queue.seed.sql) is written by hand. To add a group, add its cases file there (see the doc of
// internal/writetest) and one `test(...)` below.
//
// Only the Supabase session check is replaced: verifySubject answers the step's subject (a step with none is signed out), so
// loadAccountContext (the provisioned, not disabled club account check) and every service run for real. A subject that is
// not a club account is wrong_account (403) here; Go has no sign-in identity for it and answers 401 (the cases say so with
// goExpects).
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { afterAll, beforeAll, test, vi } from 'vitest'
import { captureWrites, openCaptureDb, root } from './capture-writes-base.mjs'

vi.mock('../../../../packages/db/src/auth/supabase.ts', async (importOriginal) => ({
  ...(await importOriginal()),
  verifySubject: async () => {
    const { currentSubject } = await import('./capture-writes-base.mjs')
    const subject = currentSubject()
    return subject ? { provider: 'supabase', subject } : null
  },
}))

const here = dirname(fileURLToPath(import.meta.url))
const testdata = resolve(here, '../../internal/queuewrites/testdata')
const apiDir = resolve(root, 'apps/queue/src/app/api')

let capture
beforeAll(async () => {
  capture = await openCaptureDb()
})
afterAll(async () => {
  await capture?.close()
})

test('roster', async () => {
  await captureWrites({ db: capture.db, testdata, name: 'roster', apiDir })
})

test('rosterops', async () => {
  await captureWrites({ db: capture.db, testdata, name: 'rosterops', apiDir })
})

// Run this group with TZ=UTC (the servers' zone): the clash texts and the dates of a repeating series read the zone.
test('prep', async () => {
  await captureWrites({ db: capture.db, testdata, name: 'prep', apiDir })
})

test('club', async () => {
  await captureWrites({ db: capture.db, testdata, name: 'club', apiDir })
})
